       _ prefs_selectionHiliteColor : NSColor,                           
       _ self_mFirstX : CanariLength,                                    
       _ self_mFirstY : CanariLength,                                    
       _ self_mSecondDx : CanariLength,                                  
       _ self_mSecondDy : CanariLength,                                  
       _ self_mRoot_mModelPointsCircleRadius : Int?
